:.8rem;right:.8rem;display:grid;place-items:center;width:1.3rem;height:1.3rem;border-radius:50%;opacity:0;background:var(--accent);color:#17251c;font-size:.75rem;font-weight:900}.selected .package-check{opacity:1}.packages strong{font-size:1.65rem;color:var(--accent)}.packages button>span:not(.package-check){font-weight:800}.packages small{margin-top:auto;color:var(--text-muted);font-size:.72rem}.checkout{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;padding:1.35rem;border:1px solid #ffffff16}.checkout h2{margin:.35rem 0 .9rem;font-size:clamp(1.3rem,3vw,2rem)}.checkout h2 span{color:var(--text-muted);font-weight:400}.checkout__summary{padding-right:1rem;border-right:1px solid #ffffff12}.checkout ul{display:grid;gap:.4rem;margin:0 0 1rem;padding:0;list-style:none;color:var(--text-muted);font-size:.85rem}.checkout li::before{content:'✓';margin-right:.45rem;color:var(--accent)}.checkout nav{display:flex;gap:.8rem;flex-wrap:wrap}.checkout__action{display:grid;gap:.8rem}.pay{display:flex;justify-content:space-between;align-items:center;padding:1rem 1.1rem;border:0;border-radius:14px;background:var(--accent);color:#17251c;font-weight:900;cursor:pointer;transition:filter .2s ease,transform .2s ease}.pay:hover:not(:disabled){filter:brightness(1.08);transform:translateY(-2px)}.pay b{font-size:1.3rem}.pay:disabled{opacity:.5;cursor:not-allowed}.message{color:#ffaaa7}.payment-history-link{color:var(--accent)}
@media(max-width:800px){.chips-hero{align-items:stretch;flex-direction:column}.economy-note{min-width:0}.packages{grid-template-columns:repeat(2,1fr)}.checkout{grid-template-columns:1fr}.checkout__summary{padding:0 0 1rem;border-right:0;border-bottom:1px solid #ffffff12}}
@media(max-width:480px){.chips-page{gap:1.1rem;padding-inline:.75rem}.chips-hero{padding:1.1rem;border-radius:21px}.packages{gap:.55rem}.packages button{min-height:125px;padding:.85rem}.packages strong{font-size:1.35rem}.section-heading{align-items:flex-start;flex-direction:column;gap:.35rem}.checkout{padding:1rem}.checkout h2{font-size:1.3rem}}
